import { analyzeGrammar, type Grammar, type GrammarSource } from './analysis'
import { TEXT_EXPORT_KINDS, buildExport, type ExportResult, type TextExportKind } from './exports'
import { ruleText, simulateLL, type LLAnalysis, type Problem } from './grammar'
import { analyzePrec, precTable, simulatePrec, type PrecSimulation, type PrecTable } from './precedence'
import type { ProjectData } from './project'
import { llTableModel, type TableModel } from './tableModel'

export { TEXT_EXPORT_KINDS, type TextExportKind }

export type LLSimulation = NonNullable<ReturnType<typeof simulateLL>>
export type TextExportResult = Extract<ExportResult, { type: 'text' | 'error' }>

/** Empty, First and Follow per nonterminal and Predict per rule, as plain lists in table column order. */
export interface LLSets {
  nonterminals: { nonterminal: string; empty: boolean; first: string[]; follow: string[] }[]
  /** One entry per rule of P; `rule` is its 1-based number. */
  predict: { rule: number; text: string; predict: string[] }[]
}

export interface ProjectAnalysis {
  /** G = (N, T, P, S) of the definition and grammar rules, including the full LL analysis (grammar.ll). */
  grammar: Grammar
  /** LL table (row = nonterminal, column = terminal, $ last; conflict flag per cell); null without grammar rules. */
  llTable: TableModel | null
  sets: LLSets | null
  /** Precedence table: terminals with $ last, one row of relations ('' = empty cell) per terminal. */
  precTable: PrecTable
  problems: { definition: Problem[]; ll: Problem[]; prec: Problem[] }
  /** LL parse of the input (symbols separated by spaces); null without grammar rules or input. */
  simulateLL(input: string): LLSimulation | null
  /** Precedence parse of the input by the reduction rules; null without reduction rules or input. */
  simulatePrec(input: string): PrecSimulation | null
  /** A text export (Markdown, CSV, LaTeX, C) of the content, or an error when its table is empty. */
  export(kind: TextExportKind): TextExportResult
}

/** The grammar texts of the content (definition + grammar rules) as the grammar module reads them. */
export const grammarSource = (data: Pick<ProjectData, 'll' | 'def'>): GrammarSource => ({ rules: data.ll.grammar, ...data.def })

// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Changes: module, agent tool and text diffs"
// Changes: Exported – the changes module compares the sets of both sides in this same shape.
export function llSets(a: LLAnalysis): LLSets {
  return {
    nonterminals: a.N.map((n) => ({
      nonterminal: n,
      empty: a.empty.has(n),
      first: a.order(a.first.get(n)!),
      follow: a.order(a.follow.get(n)!),
    })),
    predict: a.rules.map((r, i) => ({ rule: i + 1, text: ruleText(r), predict: a.order(a.predict[i]) })),
  }
}

/** Everything the app computes from the content. The grammar is analysed once; exports and simulations on demand. */
export function analyzeProject(data: ProjectData): ProjectAnalysis {
  const grammar = analyzeGrammar(grammarSource(data))
  const a = grammar.ll
  const prec = analyzePrec(data.prec)
  return {
    grammar,
    llTable: a ? llTableModel(a) : null,
    sets: a ? llSets(a) : null,
    precTable: precTable(data.prec),
    problems: { ...grammar.problems, prec: prec.problems },
    simulateLL: (input) => (a ? simulateLL(a, input) : null),
    simulatePrec: (input) => simulatePrec({ ...data.prec, input }),
    export: (kind) => buildExport(kind, data, grammar) as TextExportResult,
  }
}
